#!/bin/bash
# Download all data and models needed for this environment.
#
# Estimated total download size: 0 GB
# Estimated disk usage: ~3 MB (tracked in git)
#
# This environment has no external downloads. The visible benchmark
# (data/witb_train.json) is generated by this repository's world simulator and
# tracked in git. The method and evaluators use only the Python standard
# library. The script checks that the tracked files exist.

set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."

if [ ! -f data/witb_train.json ]; then
  echo "Missing tracked benchmark file data/witb_train.json (restore it with git checkout)." >&2
  exit 1
fi
echo "No external downloads required."
